import { readdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import path from "node:path";

const dir = path.join(process.cwd(), "src/content/guides");
const indexPath = path.join(dir, "index.ts");
const checkOnly = process.argv.includes("--check");

const files = readdirSync(dir)
  .filter((f) => f.endsWith(".json"))
  .sort();

const ident = (f: string) => "guide_" + f.replace(/\.json$/, "").replace(/[^a-zA-Z0-9]/g, "_");

const output = [
  "// Generated by scripts/sync-content-index.ts (npm run content:sync). Do not edit by hand.",
  ...files.map((f) => `import ${ident(f)} from "./${f}";`),
  "",
  "export const guideSources: unknown[] = [",
  ...files.map((f) => `  ${ident(f)},`),
  "];",
  "",
].join("\n");

const current = existsSync(indexPath) ? readFileSync(indexPath, "utf8") : "";

if (checkOnly) {
  if (current !== output) {
    console.error("❌ src/content/guides/index.ts is out of date. Run: npm run content:sync");
    process.exit(1);
  }
  console.log(`✓ Guide index in sync (${files.length} guides)`);
} else {
  writeFileSync(indexPath, output);
  console.log(`✓ Synced ${files.length} guides into src/content/guides/index.ts`);
}
